candidate.css:
:root{--ink: #23201c; --ink-soft: #4b453c; --ink-mute: #635c50; --paper: #f7f4ee; --panel: #efeae0; --card: #fffdf9; --line: #d6cfc0; --accent: #9c2b1b; --accent-dark: #7d2013; --radius: 3px;}
*, ::before, ::after{box-sizing: border-box;}
html{text-size-adjust: 100%;}
body{margin: 0px; background: var(--paper); color: var(--ink); font-family: "PingFang SC", "Hiragino Sans GB", "Source Han Sans SC", "Noto Sans CJK SC", "Microsoft YaHei", system-ui, sans-serif; font-size: 16px; line-height: 1.75;}
h1, h2, h3{margin: 0px; font-weight: 700; line-height: 1.3; letter-spacing: -0.005em;}
p{margin: 0px;}
ul, ol, dl{margin: 0px; padding: 0px;}
a{color: var(--accent);}
img{max-width: 100%; height: auto;}
.wrap{max-width: 1120px; margin: 0px auto; padding: 0px 24px;}
.narrow{max-width: 780px;}
.num{font-variant-numeric: tabular-nums; font-feature-settings: "tnum";}
[data-system-icon]{display: inline-block; width: 1em; height: 1em; vertical-align: -0.12em; font-size: 0.95em;}
a:focus-visible, button:focus-visible{outline: 2px solid var(--accent); outline-offset: 2px;}
.site-head{background: var(--paper); border-bottom: 1px solid var(--line);}
.head-row{display: flex; align-items: center; justify-content: space-between; gap: 20px; min-height: 60px; padding-top: 10px; padding-bottom: 10px;}
.brand{font-size: 18px; font-weight: 700; color: var(--ink); text-decoration: none; white-space: nowrap;}
.nav{display: flex; align-items: center; gap: 22px; font-size: 15px;}
.nav a{color: var(--ink-soft); text-decoration: none; padding: 3px 0px; border-bottom: 1px solid transparent;}
.nav a:hover{color: var(--accent); border-bottom-color: var(--accent);}
.btn{display: inline-flex; align-items: center; gap: 10px; background: var(--accent); color: rgb(255, 255, 255); text-decoration: none; font-size: 16px; font-weight: 700; padding: 13px 22px; border: 1px solid var(--accent); border-radius: var(--radius);}
.btn:hover{background: var(--accent-dark); border-color: var(--accent-dark);}
.hero{padding: 60px 0px 56px;}
.hero-grid{display: grid; grid-template-columns: minmax(0px, 1.6fr) minmax(0px, 1fr); gap: 48px; align-items: end;}
.kicker{margin: 0px; font-size: 13px; font-weight: 700; letter-spacing: 0.16em; color: var(--accent);}
.hero h1{margin-top: 14px; font-size: clamp(30px, 4.4vw, 48px); line-height: 1.16;}
.lede{margin-top: 18px; font-size: 17px; color: var(--ink-soft); max-width: 32em;}
.hero-cta{margin-top: 28px;}
.hero-side{border-left: 2px solid var(--accent); padding-left: 18px;}
.side-label{margin: 0px 0px 6px; font-size: 13px; font-weight: 700; letter-spacing: 0.08em; color: var(--ink-soft);}
.side-text{font-size: 15px; color: var(--ink-soft);}
.page-head{padding: 52px 0px 0px;}
.page-head h1{margin-top: 12px; font-size: clamp(26px, 3.4vw, 38px);}
.page-head .lede{margin-top: 16px;}
.sec{padding: 60px 0px;}
.sec + .sec{border-top: 1px solid var(--line);}
.sec-alt{background: var(--panel);}
.sec h2{font-size: 24px;}
.sec-head{margin-bottom: 22px;}
.sec-sub{margin-top: 8px; font-size: 15px; color: var(--ink-soft); max-width: 36em;}
.text{margin-top: 16px; font-size: 16px; color: var(--ink-soft); max-width: 36em;}
.sec-link{margin-top: 20px; font-size: 15px; font-weight: 700;}
.sec-link a{color: var(--accent); text-decoration: none; border-bottom: 1px solid var(--accent); padding-bottom: 2px;}
.sec-link a:hover{color: var(--accent-dark); border-bottom-color: var(--accent-dark);}
.cmp{display: grid; margin-top: 22px; border-top: 2px solid var(--ink);}
.cmp-row{display: grid; grid-template-columns: 150px minmax(0px, 1fr) 140px 220px; gap: 6px 24px; padding: 18px 0px; border-bottom: 1px solid var(--line);}
.cmp dt{margin: 0px; font-size: 17px; font-weight: 700; color: var(--ink);}
.cmp dd{margin: 0px; font-size: 15px; color: var(--ink-soft); overflow-wrap: break-word;}
.term-label{font-size: 12px; font-weight: 700; letter-spacing: 0.06em; color: var(--ink-soft);}
.cmp .term-label{display: block; margin-bottom: 2px;}
.terms{margin-top: 20px; padding-top: 16px; border-top: 2px solid var(--ink); display: grid; grid-template-columns: repeat(2, minmax(0px, 1fr)); gap: 18px 40px;}
.terms dt{font-size: 12px; font-weight: 700; letter-spacing: 0.06em; color: var(--ink-soft);}
.terms dd{margin: 4px 0px 0px; font-size: 17px; font-weight: 700; color: var(--ink); overflow-wrap: break-word;}
.prod-side > .terms{margin-top: 0px; padding-top: 0px; border-top: 0px; grid-template-columns: 1fr; gap: 16px;}
.table-scroll{margin-top: 22px;}
.spec-table{width: 100%; border-collapse: collapse; font-size: 15px;}
.spec-table th, .spec-table td{text-align: left; vertical-align: top; padding: 12px 14px; border-bottom: 1px solid var(--line); overflow-wrap: break-word;}
.spec-table thead th{font-size: 13px; font-weight: 700; color: var(--ink-soft);}
.spec-table tbody th{font-weight: 700; color: var(--ink); width: 20%;}
.spec-table td{color: var(--ink-soft);}
.table-note{margin-top: 12px; font-size: 14px; color: var(--ink-soft); max-width: 40em;}
.prod-head h2{font-size: 24px;}
.prod-head p{margin-top: 8px; font-size: 15px; color: var(--ink-soft); max-width: 34em;}
.prod-body{display: grid; grid-template-columns: minmax(0px, 1.4fr) minmax(0px, 1fr); gap: 44px; align-items: start; margin-top: 22px;}
.prod-body-rev{grid-template-columns: minmax(0px, 1fr) minmax(0px, 1.15fr);}
.prod-body .table-scroll{margin-top: 0px;}
.spec-dl{display: grid;}
.spec-dl > div{display: grid; grid-template-columns: 110px minmax(0px, 1fr); gap: 16px; padding: 12px 0px; border-bottom: 1px solid var(--line);}
.spec-dl dt{font-weight: 700; color: var(--ink);}
.spec-dl dd{margin: 0px; color: var(--ink-soft);}
.limit-note{border-left: 2px solid var(--accent); padding-left: 16px; font-size: 15px; color: var(--ink-soft); max-width: 32em;}
.cap-grid{display: grid; grid-template-columns: minmax(0px, 1fr) minmax(0px, 1fr); gap: 48px;}
.plain-list{margin-top: 18px; list-style: none; max-width: 22em; font-size: 16px; color: var(--ink-soft);}
.plain-list li{padding: 9px 0px; border-bottom: 1px solid var(--line);}
.cap-list{margin-top: 18px; display: flex; flex-wrap: wrap; gap: 10px 30px; list-style: none; font-size: 16px; color: var(--ink-soft);}
.equip{margin-top: 18px;}
.equip > div{display: flex; align-items: baseline; justify-content: space-between; gap: 16px; padding: 9px 0px; border-bottom: 1px solid var(--line);}
.equip dt{font-size: 15px; color: var(--ink-soft);}
.equip dd{margin: 0px; font-size: 17px; font-weight: 700; color: var(--ink); font-variant-numeric: tabular-nums;}
.equip-grid{margin-top: 22px; display: grid; grid-template-columns: repeat(3, minmax(0px, 1fr)); gap: 22px 32px;}
.equip-grid dt{font-size: 15px; color: var(--ink-soft);}
.equip-grid dd{margin: 4px 0px 0px; font-size: 18px; font-weight: 700; color: var(--ink); font-variant-numeric: tabular-nums;}
.steps{margin-top: 22px; padding-left: 1.4em; list-style: decimal; max-width: 36em; font-size: 16px; color: var(--ink-soft);}
.steps li{margin-bottom: 16px;}
.steps li:last-child{margin-bottom: 0px;}
.steps strong{display: block; font-size: 16px; color: var(--ink);}
.faq{margin-top: 22px; max-width: 38em;}
.faq > div{padding: 16px 0px; border-bottom: 1px solid var(--line);}
.faq dt{font-weight: 700; color: var(--ink);}
.faq dd{margin: 6px 0px 0px; color: var(--ink-soft);}
.boundary{border-left: 2px solid var(--accent); padding-left: 18px; font-size: 17px; color: var(--ink); max-width: 38em;}
.inquiry-grid{display: grid; grid-template-columns: minmax(0px, 1fr) minmax(0px, 1.1fr); gap: 48px; align-items: start;}
.inquiry-block{background: var(--card); border: 1px solid var(--line); border-radius: var(--radius); padding: 22px;}
.contact-grid{display: grid; grid-template-columns: minmax(0px, 1fr) minmax(0px, 1.15fr); gap: 48px; align-items: start;}
.contact-item{margin-bottom: 26px;}
.contact-item:last-child{margin-bottom: 0px;}
.contact-item h2{font-size: 15px; font-weight: 700; letter-spacing: 0.06em; color: var(--ink-soft); margin-bottom: 6px;}
.contact-item p{font-size: 16px; color: var(--ink-soft); max-width: 26em;}
.mail{font-size: 19px; font-weight: 700; color: var(--ink); overflow-wrap: break-word;}
.site-foot{background: var(--panel); border-top: 1px solid var(--line); padding: 40px 0px 32px;}
.foot-grid{display: grid; grid-template-columns: 1.4fr 1fr 1fr; gap: 36px;}
.site-foot p{margin: 0px 0px 6px;}
.site-foot p:last-child{margin-bottom: 0px;}
.foot-brand{font-size: 17px; font-weight: 700;}
.foot-text{font-size: 14px; color: var(--ink-soft); max-width: 30em;}
.foot-label{font-size: 13px; font-weight: 700; letter-spacing: 0.08em; color: var(--ink-soft);}
.foot-list{list-style: none; display: grid; gap: 6px; font-size: 14px;}
.foot-list a{color: var(--ink-soft); text-decoration: none;}
.foot-list a:hover{color: var(--accent); text-decoration: underline;}
@media (max-width: 900px){.hero{padding: 48px 0px 44px;}
.hero-grid{grid-template-columns: 1fr; gap: 32px; align-items: start;}
.cmp-row{grid-template-columns: 1fr; gap: 10px; padding: 16px 0px;}
.prod-body, .prod-body-rev{grid-template-columns: 1fr; gap: 28px;}
.cap-grid, .inquiry-grid, .contact-grid{grid-template-columns: 1fr; gap: 32px;}
.foot-grid{grid-template-columns: 1fr 1fr;}}
@media (max-width: 640px){.wrap{padding: 0px 18px;}
.sec{padding: 44px 0px;}
.sec h2, .prod-head h2{font-size: 21px;}
.head-row{gap: 14px;}
.brand{font-size: 16px;}
.nav{gap: 14px; font-size: 13.5px;}
.hero h1{font-size: 30px;}
.lede, .text{font-size: 16px;}
.foot-grid{grid-template-columns: 1fr; gap: 24px;}
.equip-grid{grid-template-columns: 1fr; gap: 16px;}
.spec-dl > div{grid-template-columns: 88px minmax(0px, 1fr); gap: 12px;}
.spec-table{font-size: 14px;}
.spec-table th, .spec-table td{padding: 10px;}
.spec-table tbody th{width: 84px;}
.terms{grid-template-columns: 1fr; gap: 16px;}}
@media (max-width: 420px){.head-row{flex-wrap: wrap; gap: 10px 14px;}
.nav{flex-wrap: wrap; gap: 12px;}}
